using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.Invoices.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;namespace Namaa.Application.Invoices.Commands.CancelInvoice;public sealed class CancelInvoiceCommandHandler(IInvoiceRepository repository,IApplicationDbContext db):IRequestHandler<CancelInvoiceCommand,Result<InvoiceDto>>{public async Task<Result<InvoiceDto>>Handle(CancelInvoiceCommand request,CancellationToken cancellationToken){var e=await repository.FindForUpdateAsync(request.Id,cancellationToken);if(e is null)return Result.Failure<InvoiceDto>(InvoiceErrors.NotFound);if(e.Status.ToString() is not ("Draft" or "Issued"))return Result.Failure<InvoiceDto>(InvoiceErrors.NotDraft);e.Cancel();await db.SaveChangesAsync(cancellationToken);return Result.Success(InvoiceDto.FromEntity(e));}}
